import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const config = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: () => {},
    onDblClick: () => null,
    delete: enrolledCustomer =>
      methods.deleteEnrolledCustomer(enrolledCustomer),
  },
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  page: 1,
  rowsPerPage: 6,
  rowOffsetHeight: 55,
  itemKey: 'customer.name',
  sortBy: 'customer.name',
  sortDesc: false,
  itemsPerRow: {
    withoutDetail: {
      lg: 3,
      xl: 4,
    },
  },
  showChipComponent: {
    itemKey: 'status',
    color: enrolledCustomer => methods.getChipColor(enrolledCustomer),
    value: enrolledCustomer => methods.getStatusText(enrolledCustomer),
  },
  headers: [
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.name'
      ),
      align: 'start',
      value: 'customer.name',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.phone'
      ),
      value: 'phone',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.awardAmount'
      ),
      value: 'amount',
      format: item => formatNumberFromDbToCurrency(item),
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.pendingAmount'
      ),
      value: 'amountPending',
      format: item => formatNumberFromDbToCurrency(item),
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.lastSale'
      ),
      value: 'customer.lastSaleDate',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.status'
      ),
      value: 'status',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramView.table.headers.actions'
      ),
      value: 'actions',
      sortable: false,
      align: 'end',
    },
  ],
  slotColumns: ['phone'],
})

export default config
