<template>
  <v-row no-gutters>
    <v-col cols="5" class="px-2 mr-10" align-self="center">
      <MobileMockup
        class="mobile"
        :message="processedText"
        :messageTitle="messageTitle"
        :messageFooter="
          getTranslatedText(
            'loyaltyProgramView.sendNotificationsDialog.steps.step1.messageFooter'
          )
        "
      />
    </v-col>
    <v-col cols="6" class="px-2 py-4" align-self="center">
      <FormattedText
        intl
        value="loyaltyProgramView.sendNotificationsDialog.steps.step3.description"
        typeText="text-body-1"
      />
      <FormattedText class="mt-2" :value="customers" typeText="text-body-1" />
      <v-img
        :src="require('@/assets/confirmation.svg')"
        alt="confirmation"
        class="mt-10 mx-auto"
        max-height="280"
        contain
      />
    </v-col>
  </v-row>
</template>

<script>
import { isNil } from 'ramda'

import { getTranslatedText } from '@/tools/data'

import MobileMockup from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/MobileMockup'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ReviewData',
  components: { MobileMockup, FormattedText },
  props: {
    data: {
      type: Object,
      required: true,
    },
  },
  computed: {
    processedText() {
      const template = this.data.templateSelected?.message
      if (isNil(template)) return ''
      const formData = this.data.formData
      return template.replace(/\{([\w-]+):[\w-]+\}/g, (match, key) => {
        return formData[key] || match
      })
    },
    messageTitle() {
      return this.data.templateSelected?.messageTitle || ''
    },
    customers() {
      return this.getTranslatedText(
        'loyaltyProgramView.sendNotificationsDialog.steps.step3.customersSelected',
        this.data.customersToNotify.length
      )
    },
  },
  methods: {
    getTranslatedText,
  },
}
</script>
