import light from '@/themes/light'
import dark from '@/themes/dark'

export const setTableConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: () => {},
    onDblClick: () => {},
  },
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  page: 1,
  rowsPerPage: 10,
  rowOffsetHeight: 48,
  itemKey: 'customerId',
  sortBy: 'name',
  sortDesc: false,
  headers: [
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramConfig.stepper.step2.headers.name'
      ),
      value: 'customer.name',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.loyaltyProgramConfig.stepper.step2.headers.phone'
      ),
      value: 'customer.phone',
      format: item => item,
    },
  ],
})

export default setTableConfig
