<template>
  <v-hover>
    <template>
      <v-card
        flat
        color="cardBackgroundSecondary"
        class="card-container rounded-lg"
        :class="{ 'disabled-b': data.disabled }"
        @click="data.action"
      >
        <div class="card-icon">
          <v-icon color="primary" size="50">{{ data.icon }}</v-icon>
        </div>
        <div class="info-detail">
          <div class="info-description pr-10">
            <FormattedText
              intl
              :value="data.label"
              type="text-h6"
              className="font-weight-bold"
            />
            <FormattedText
              v-if="infoToText"
              :value="infoToText"
              shorter
              :shorterValue="trucateLength"
              :title="infoToText"
            />
          </div>
        </div>
      </v-card>
    </template>
  </v-hover>
</template>

<script>
import { isNil } from 'ramda'

import { getTranslatedText } from '@/tools/data'
import { formatDate } from '@/tools/dates'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'InfoCard',
  components: { FormattedText },
  props: {
    data: {
      type: Object,
      required: true,
      default: () => ({
        icon: 'mdi-emoticon-happy-outline',
        label: 'Titulo',
        info: 'Pues aqui estamos',
        disabled: false,
        action: () => {},
      }),
    },
  },
  computed: {
    trucateLength() {
      switch (this.$vuetify.breakpoint.name) {
        case 'lg':
          return '100'
        case 'xl':
          return '150'
        default:
          return '50'
      }
    },
    infoToText() {
      if (isNil(this.data.info)) return
      return typeof this.data.info === 'string'
        ? this.data.info
        : this.formatNumberFromDbToCurrency(this.data.info)
    },
  },
  methods: {
    getTranslatedText,
    formatDate,
    formatNumberFromDbToCurrency,
  },
}
</script>

<style lang="scss" scoped>
.card-container {
  display: flex;
  overflow: hidden;
  height: 70px;
  max-width: 500px;
  .card-icon {
    display: flex;
    width: 70px;
    align-items: center;
    justify-content: center;
    border-top-right-radius: 0 !important;
  }
  .info-detail {
    width: 100%;
    display: flex;
    line-height: 1;
    .info-description {
      display: flex;
      flex-direction: column;
      justify-content: center;
      flex-grow: 1;
      padding: 4px 14px 8px 14px;
      :deep(.info-description-text) {
        line-height: 2;
      }
    }
  }
}
.disabled-b {
  opacity: 0.5;
  filter: grayscale(1);
  cursor: not-allowed !important;
}
</style>
