<template>
  <v-btn
    :disabled="disabled || !isButtonEnabled"
    :loading="disabled || !isButtonEnabled"
    @click="onConfirm"
    class="timer-button custom-disabled-style"
    color="primary"
  >
    <FormattedText
      v-if="text"
      :type="textType"
      :className="textClass"
      :value="countdownText"
      :color="textColor"
    />
    <template v-slot:loader>
      <div class="progress-bar" :style="{ width: progressWidth + '%' }"></div>
      <span class="text-loading d-flex">
        <FormattedText
          :type="textTypeLoader"
          :className="textClassLoader"
          :value="countdownText"
          :color="textColorLoader"
        />
      </span>
    </template>
  </v-btn>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ButtonCountdown',
  components: { FormattedText },
  props: {
    text: {
      type: String,
      default: '',
    },
    textType: {
      type: String,
      default: '',
    },
    textClass: {
      type: String,
      default: '',
    },
    textColor: {
      type: String,
      default: 'white',
    },
    textLoader: {
      type: String,
      default: '',
    },
    textTypeLoader: {
      type: String,
      default: '',
    },
    textClassLoader: {
      type: String,
      default: '',
    },
    textColorLoader: {
      type: String,
      default: '#E0E0E0',
    },
    intl: {
      type: Boolean,
      default: false,
    },
    intlLoader: {
      type: Boolean,
      default: false,
    },
    duration: {
      type: Number,
      default: 10,
    },
    action: {
      type: Function,
      required: true,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      timer: this.duration * 1000,
      interval: null,
      progressWidth: 100,
      isButtonEnabled: false,
    }
  },
  computed: {
    countdownText() {
      return `${this.getTranslatedText(this.text)} (${Math.ceil(
        this.timer / 1000
      )})`
    },
  },
  methods: {
    getTranslatedText,
    startCountdown() {
      const startTime = Date.now()
      this.interval = setInterval(() => {
        const elapsed = Date.now() - startTime
        this.timer = this.duration * 1000 - elapsed
        this.progressWidth = (this.timer / (this.duration * 1000)) * 100
        if (this.timer <= 0) {
          clearInterval(this.interval)
          this.isButtonEnabled = true
          this.progressWidth = 0
          this.timer = 0
        }
      }, 1000)
    },
    onConfirm() {
      this.action()
    },
  },
  mounted() {
    if (this.disabled) return
    this.startCountdown()
  },
  beforeDestroy() {
    clearInterval(this.interval)
  },
}
</script>

<style lang="scss" scoped>
.timer-button {
  position: relative;
  overflow: hidden;
  background-color: #8bc34a;
  color: white;
}
.text-loading {
  z-index: 100;
}
.progress-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #689f38;
  transition: width 1s linear;
}
.v-btn.v-btn--disabled.v-btn--has-bg.custom-disabled-style {
  background-color: #8bc34a !important;
}
</style>
