import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'
import { loyaltyNotificationType } from '@/config/loyaltyProgram'

import { formatNumberFromDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import customersActions from '@/store/customers/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'

const getLoyaltyInfo = function() {
  const isOnline = this.hasInternetConnection
  return [
    {
      id: 1,
      icon: 'mdi-trophy-outline',
      label: 'loyaltyProgramView.cards.titleAwardAmount',
      info: this.account.loyaltyProgram.rewardAmount,
      action: this.openSettingsDialog,
    },
    {
      id: 2,
      icon: 'mdi-gift-outline',
      label: 'loyaltyProgramView.cards.titlePrize',
      info: this.account.loyaltyProgram.prizeDescription,
      action: this.openSettingsDialog,
    },
    {
      id: 3,
      icon: 'mdi-cellphone-message',
      label: 'loyaltyProgramView.cards.sendNotifications',
      disabled: !isOnline,
      action: () => {
        this.$track({
          type: 'interaction',
          action: 'click',
          category: 'LoyaltyProgram',
          screen: 'EnrolledCustomerList',
          name: 'Open send notifications',
        })
        if (!isOnline) return
        this.openSendNotificationsDialog(loyaltyNotificationType.NOTIFICATION)
      },
    },
    {
      id: 4,
      icon: 'mdi-sale',
      label: 'loyaltyProgramView.cards.sendPromotions',
      disabled: !isOnline,
      action: () => {
        this.$track({
          type: 'interaction',
          action: 'click',
          category: 'LoyaltyProgram',
          screen: 'EnrolledCustomerList',
          name: 'Open send promotions',
        })
        if (!isOnline) return
        this.openSendNotificationsDialog(loyaltyNotificationType.PROMOTION)
      },
    },
  ]
}

const updateAmountForEachEnrolledCustomer = function(enrolledCustomers) {
  return enrolledCustomers.map(enrolledCustomer => {
    return {
      ...enrolledCustomer,
      amount: formatNumberFromDb(enrolledCustomer.amount),
    }
  })
}

const getStatusChipText = function(enrolledCustomer) {
  switch (enrolledCustomer.status) {
    case 1:
      return this.getTranslatedText(
        'loyaltyProgramView.enrolledCustomer.status.enrolled'
      )
    case 0:
      return this.getTranslatedText(
        'loyaltyProgramView.enrolledCustomer.status.pending'
      )
    case 2:
      if (!this.isCorrectPhoneNumber(enrolledCustomer.customer.phone)) {
        return this.getTranslatedText(
          'loyaltyProgramView.enrolledCustomer.status.noPhone'
        )
      }
      return this.getTranslatedText(
        'loyaltyProgramView.enrolledCustomer.status.invitationNotSent'
      )
    default:
      return this.getTranslatedText(
        'loyaltyProgramView.enrolledCustomer.status.unknown'
      )
  }
}

const getStatusChipColor = function(enrolledCustomer) {
  switch (enrolledCustomer.status) {
    case 1:
      return 'chipPrimary'
    case 0:
      return 'chipSecondary'
    default:
      if (!this.isCorrectPhoneNumber(enrolledCustomer.customer.phone)) {
        return 'chipError'
      }
      return 'chipAccent'
  }
}

const createSynchronizationOperation = function(customer) {
  rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
    event: SYNCHRONIZATION_EVENTS.events.createOperation.name,
    data: {
      entityData: JSON.parse(JSON.stringify(customer)),
      entityName: 'customers',
    },
  })
}

const updateCustomerAndEnrolledCustomerStore = function(customer) {
  this[customersActions.editCustomerField]({
    id: customer._id,
    phone: customer.mobile_number,
  })
  this[loyaltyProgramActions.updateEnrolledCustomerByProperties]({
    customerId: customer._id,
    customer: { phone: customer.mobile_number },
  })
}

const sendInvitationToCustomerWithPhoneEdited = function(customer) {
  const enrolledCustomerFound = this.getFilteredData.find(
    enrolledCustomer => enrolledCustomer.customerId === customer._id
  )
  if (enrolledCustomerFound && enrolledCustomerFound.status !== 1) {
    this.resendInvitations([enrolledCustomerFound])
  }
}

export default {
  getLoyaltyInfo,
  updateAmountForEachEnrolledCustomer,
  getStatusChipText,
  getStatusChipColor,
  createSynchronizationOperation,
  updateCustomerAndEnrolledCustomerStore,
  sendInvitationToCustomerWithPhoneEdited,
}
