<template>
  <v-autocomplete
    :id="id"
    ref="autocomplete"
    :label="label"
    v-model="selectedProduct"
    :items="items"
    :loading="loading"
    :filter="customFilter"
    :item-text="itemText"
    :item-value="itemValue"
    :class="className"
    background-color="cardBackgroundSecondary"
    :return-object="returnObject"
    :error-messages="errorMessage"
    :clearable="clearable"
    :menu-props="menuProps"
    filled
    rounded
    :readonly="readonly"
    @update:search-input="searchVal => $emit('searchInputUpdated', searchVal)"
    @blur="onBlur"
    @focus="e => $emit('focus', e)"
  >
    <!-- List item -->
    <template v-slot:item="data">
      <v-list-item-avatar tile>
        <v-avatar>
          <CategoryIcon
            :categoryName="data.item.categoryName"
            :iconSize="{ x: 40, y: 40 }"
            v-if="isProductInInventory(data.item)"
          />
          <v-icon x-large color="primary" v-else> mdi-plus-circle</v-icon>
        </v-avatar>
      </v-list-item-avatar>
      <v-list-item-content class="product-list">
        <v-list-item-title>
          <b>
            {{
              `${data.item.name} ${data.item.alternativeName || ''}`
                | truncate(50)
            }}
          </b>
        </v-list-item-title>
        <v-list-item-subtitle class="d-flex">
          <span>
            <v-icon>mdi-barcode-scan</v-icon>
            {{ data.item.upc }}
          </span>
          <span class="ml-4" v-if="isProductInInventory(data.item)">
            <v-icon>mdi-basket-fill</v-icon>
            {{ data.item.quantity }}
          </span>
          <slot name="extraInfo" :item="data.item" />
          <span
            class="ml-4 d-flex align-center"
            v-if="!isProductInInventory(data.item)"
          >
            <v-icon color="secondary">mdi-information-outline</v-icon>
            <FormattedText
              intl
              value="shared.addToStore"
              type="text-body-2"
              color="textPrimary"
            />
          </span>
        </v-list-item-subtitle>
      </v-list-item-content>
    </template>
  </v-autocomplete>
</template>

<script>
import CategoryIcon from '@/components/shared/CategoryIcon'
import FormattedText from '@/components/shared/FormattedText'
export default {
  name: 'ProductAutoComplete',
  components: { CategoryIcon, FormattedText },
  props: {
    id: {
      type: String,
    },
    label: {
      type: String,
    },
    value: {
      type: [Object, String, Number],
      default: null,
    },
    items: {
      type: Array,
      required: true,
    },
    itemText: {
      type: String,
      default: 'name',
    },
    itemValue: {
      type: String,
      default: 'id',
    },
    className: {
      type: String,
    },
    returnObject: {
      type: Boolean,
      default: false,
    },
    errorMessage: {
      type: [String, Array],
      default() {
        return []
      },
    },
    clearable: {
      type: Boolean,
      default: false,
    },
    customFilter: {
      type: Function,
    },
    onBlur: {
      type: Function,
      default: () => {},
    },
    menuProps: {
      type: Object,
      default: () => ({}),
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    selectedProduct: {
      get() {
        return this.value
      },
      set(newValue) {
        this.$emit('input', newValue)
      },
    },
  },
  methods: {
    isProductInInventory(product) {
      if (!('isStoreInventory' in product)) return 'vendorCode' in product
      return product.isStoreInventory === 1
    },
    blur() {
      this.$refs.autocomplete.blur()
    },
  },
}
</script>
