<template>
  <DialogCard :config="componentConfig.dialogData">
    <LoyaltySettingsForm
      :loyaltyConfig="account.loyaltyProgram"
      :onEnterEvent="saveSettings"
    />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import setConfig from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltySettingsDialog/config'

import DialogCard from '@/components/shared/DialogCard'
import LoyaltySettingsForm from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltySettingsDialog/LoyaltySettingsForm'

export default {
  name: 'LoyaltySettingsDialog',
  components: { DialogCard, LoyaltySettingsForm },
  data() {
    return {
      formPayload: {},
      isAcceptButtonDisabled: true,
    }
  },
  computed: {
    ...mapState('loyaltyProgramView', ['settingsDialog']),
    ...mapState('account', {
      account: state => state.data,
    }),
    componentConfig() {
      return setConfig(
        {
          isOpen: this.settingsDialog.isOpen,
          isAcceptButtonDisabled: this.isAcceptButtonDisabled,
        },
        {
          closeDialog: this.closeDialog,
          saveSettings: this.saveSettings,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setSettingsDialogStatus,
      loyaltyProgramViewActions.setConfirmSettingDialogStatus,
    ]),
    closeDialog() {
      this[loyaltyProgramViewActions.setSettingsDialogStatus](false)
    },
    saveSettings() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'LoyaltySettingsDialog',
        name: 'Submit',
      })
      this[loyaltyProgramViewActions.setConfirmSettingDialogStatus]({
        isOpen: true,
        formPayload: this.formPayload,
      })
    },
  },
  mounted() {
    this.$root.$on('loyalty-settings-config', payload => {
      if (payload.isValid === false) {
        this.isAcceptButtonDisabled = true
        return
      }
      this.formPayload = payload
      this.isAcceptButtonDisabled = false
    })
  },
}
</script>
