<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import setConfig from '@/components/LoyaltyViews/LoyaltyProgramView/DeleteEnrolledCustomerDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteEnrolledCustomerDialog',
  components: { DialogCard },
  data() {
    return {
      enrolledCustomerRemove: false,
    }
  },
  computed: {
    ...mapState('loyaltyProgramView', ['deleteEnrolledCustomerDialog']),
    ...mapState('account', { accountData: state => state.data }),
    dialogConfig() {
      return setConfig(
        {
          opened: this.deleteEnrolledCustomerDialog.isOpen,
          multiple:
            this.deleteEnrolledCustomerDialog.selectedEnrolledCustomer.length >
            1,
        },
        {
          closeDialog: this.closeDialog,
          removeEnrolledCustomer: this.removeEnrolledCustomer,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus,
    ]),
    closeDialog() {
      if (this.deleteEnrolledCustomerDialog.inBulk) {
        this.$root.$emit('delete-enrolled-customer-cancel')
      }
      this[loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus]({
        isOpen: false,
      })
    },
    removeEnrolledCustomer() {
      if (this.enrolledCustomerRemove) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'DeleteEnrolledCustomerDialog',
        name: 'Confirm',
      })
      this.enrolledCustomerRemove = true
      rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
        event:
          ENROLLED_CUSTOMERS_DB_API_EVENTS.events.deleteEnrolledCustomers.name,
        data: {
          enrolledCustomers: [
            ...this.deleteEnrolledCustomerDialog.selectedEnrolledCustomer,
          ],
          securityData: this.accountData.security,
          phoneCode: this.accountData.country.phoneCode,
          storeName: this.accountData.storeName,
          inBulk: this.deleteEnrolledCustomerDialog.inBulk,
        },
      })
    },
    async enrolledCustomersListener(event, payload) {
      const deleteEnrolledCustomerReplies =
        ENROLLED_CUSTOMERS_DB_API_EVENTS.events.delete.replies
      const replies = {
        [deleteEnrolledCustomerReplies.success]: () => {
          this.enrolledCustomerRemove = false
        },
        [deleteEnrolledCustomerReplies.error]: () => {
          this.enrolledCustomerRemove = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
  },
}
</script>
