<template>
  <div class="d-flex flex-column pa-4">
    <MoneyTextField
      id="reward-amount-input"
      ref="rewardAmount"
      v-model.number="inputs.rewardAmount"
      :config="{
        fieldName: 'rewardAmount',
        label: getTranslatedText(
          'loyaltyProgramView.settingsDialog.awardAmountPlaceholder'
        ),
        color: 'primary',
        filled: true,
        rounded: true,
        class: 'custom-text-field-large',
        prependIcon: 'mdi-trophy-outline',
        errorMessage: onValidateFields,
      }"
      :options="moneyInputConfig"
      @keydown.enter="onEnterEvent"
      @input="emitValues"
      @blur="$v.inputs.rewardAmount.$touch()"
    />
    <v-text-field
      id="prize-description-input"
      ref="prizeDescription"
      v-model="inputs.prizeDescription"
      class="custom-text-field-large"
      filled
      rounded
      color="primary"
      counter="200"
      :label="
        getTranslatedText('loyaltyProgramView.settingsDialog.prizePlaceholder')
      "
      prepend-inner-icon="mdi-gift-outline"
      :error-messages="onValidateFields('prizeDescription')"
      @keydown.enter="onEnterEvent"
      @input="emitValues"
      @blur="$v.inputs.prizeDescription.$touch()"
    />
  </div>
</template>

<script>
import { required, maxLength } from 'vuelidate/lib/validators'

import { getTranslatedText } from '@/tools/data'
import {
  formatNumberFromDb,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import { validate } from '@/tools/validations'

import MoneyTextField from '@/components/shared/MoneyTextField'

export default {
  name: 'LoyaltySettingsForm',
  components: { MoneyTextField },
  props: {
    loyaltyConfig: {
      type: Object,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
  },
  data() {
    return {
      inputs: {
        rewardAmount: 0,
        prizeDescription: '',
      },
    }
  },
  computed: {
    moneyInputConfig() {
      const { currency, locale, prefix } = moneyTextFieldCountryConfig()
      return { currency, locale, prefix, precision: 0 } || { precision: 2 }
    },
  },
  methods: {
    getTranslatedText,
    initForm() {
      this.inputs.rewardAmount = formatNumberFromDb(
        this.loyaltyConfig.rewardAmount
      )
      this.inputs.prizeDescription = this.loyaltyConfig.prizeDescription
      this.$nextTick(() => {
        this.$v.inputs.rewardAmount.$touch()
      })
    },
    setFormValidators() {
      return {
        inputs: {
          rewardAmount: {
            required,
            minValue: value => value > 0,
            maxValue: value => value < 1000000,
          },
          prizeDescription: {
            maxLength: maxLength(200),
          },
        },
      }
    },
    onValidateFields(input) {
      return validate(this.$v.inputs, input, {
        fn: this.getTranslatedText,
        key: 'loyaltyProgramView.settingsDialog.form',
      })
    },
    emitValues() {
      this.$root.$emit('loyalty-settings-config', {
        inputs: this.inputs,
        isValid: !this.$v.$invalid,
        loyaltyConfig: this.loyaltyConfig,
      })
    },
  },
  validations() {
    return this.setFormValidators()
  },
  mounted() {
    this.initForm()
  },
  updated() {
    this.emitValues()
  },
}
</script>
