<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import config from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltyToolbar/Filters/config'

import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'LoyaltyFilters',
  components: {
    ToolBar,
  },
  computed: {
    ...mapState('loyaltyProgramView', ['filters']),
    componentConfig() {
      return config(
        { filters: this.filters },
        {
          setSearchTerm: this[loyaltyProgramViewActions.setSearchTermFilter],
          inviteCustomer: this.inviteCustomers,
        }
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setSearchTermFilter,
      loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus,
    ]),
    inviteCustomers() {
      this[loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus](true)
    },
  },
  mounted() {
    if (this.$route.query.search) {
      this[loyaltyProgramViewActions.setSearchTermFilter](
        this.$route.query.search
      )
      this.$root.$emit('default-value', {
        input: 'search-control',
        value: this.$route.query.search,
      })
      this.$router.replace({ query: {} })
    }
  },
}
</script>
