<template>
  <div class="fill-height px-3">
    <PaginatedTableSelection
      :config="tableComponentConfig"
      @updateSelectedItems="updateSelectedCustomers"
    >
      <template v-slot:top>
        <div class="d-flex flex-column mb-5">
          <div
            class="d-flex align-center justify-space-between pb-2 paginated-table__header"
          >
            <div class="d-flex align-center">
              <v-icon color="primary" large>mdi-hand-heart-outline</v-icon>
              <FormattedText
                intl
                type="title"
                color="textPrimary"
                value="loyaltyProgramView.title"
                class="pl-2"
              />
            </div>
          </div>
          <div class="d-flex justify-space-between">
            <div class="d-flex justify-start">
              <div
                v-for="item in loyaltyInfo"
                :key="item.id"
                class="pointer no-user-select mr-4"
              >
                <InfoCard :data="item" class="info-card" />
              </div>
            </div>
          </div>
        </div>
        <div class="d-flex justify-end py-2">
          <v-btn
            text
            class="mr-2"
            color="primary"
            :disabled="!enableResendInvitationsGroupBtn"
            @click="resendInvitations(selectedCustomers)"
            v-track:click="{
              category: 'LoyaltyProgram',
              screen: 'EnrolledCustomerList',
              name: 'Resend invitation bulk',
            }"
          >
            <v-icon class="mr-2">mdi-email-fast-outline</v-icon>
            {{
              getTranslatedText(
                'loyaltyProgramView.table.toolbar.sendInvitations'
              )
            }}
          </v-btn>
          <v-btn
            color="error"
            text
            :disabled="enableDeleteGroupBtn"
            @click="deleteEnrolledCustomersInBulk()"
            v-track:click="{
              category: 'LoyaltyProgram',
              screen: 'EnrolledCustomerList',
              name: 'Delete enrolled customer bulk',
            }"
          >
            <v-icon class="mr-2">mdi-delete</v-icon>
            {{ getTranslatedText('loyaltyProgramView.table.toolbar.delete') }}
          </v-btn>
        </div>
      </template>
      <template v-slot:phone="{ item }">
        <span v-if="isCorrectPhoneNumber(item.customer.phone)">
          {{ item.customer.phone }}
        </span>
        <InputPhone v-else :customer="item.customer" />
      </template>
      <template v-slot:actions="{ item }">
        <div class="d-flex justify-end">
          <v-tooltip
            bottom
            :disabled="item.status === 1 || canSendInvitation(item)"
            max-width="200px"
          >
            <template v-slot:activator="{ on }">
              <div v-on="on" class="d-inline-block">
                <Button
                  iconBtn
                  iconColorDark="primary"
                  textColor="primary"
                  icon="mdi-email-fast-outline"
                  class="mr-2"
                  :disabled="!canSendInvitation(item)"
                  tooltipText="loyaltyProgramView.table.tooltips.sendInvitation"
                  tooltipPosition="bottom"
                  @click="resendInvitations([item])"
                  v-track:click="{
                    category: 'LoyaltyProgram',
                    screen: 'EnrolledCustomerList',
                    name: 'Resend invitation',
                  }"
                />
              </div>
            </template>
            <FormattedText
              value="loyaltyProgramView.table.tooltips.correctPhone"
              intl
              color="white"
            />
          </v-tooltip>
          <Button
            iconBtn
            iconColorDark="error"
            textColor="error"
            icon="mdi-delete"
            tooltipText="loyaltyProgramView.table.tooltips.delete"
            tooltipPosition="bottom"
            @click="deleteEnrolledCustomer(item)"
            v-track:click="{
              category: 'LoyaltyProgram',
              screen: 'EnrolledCustomerList',
              name: 'Delete enrolled customer',
            }"
          />
        </div>
      </template>
    </PaginatedTableSelection>
    <LoyaltySettingsDialog v-if="settingsDialog.isOpen" />
    <ConfirmDialog v-if="confirmSettingDialog.isOpen" />
    <DeleteEnrolledCustomerDialog v-if="deleteEnrolledCustomerDialog.isOpen" />
    <AddEnrolledCustomersDialog v-if="addEnrolledCustomersDialog.isOpen" />
    <SendNotificationsDialog v-if="sendNotificationsDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'

import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'
import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'
import { enrolStatus } from '@/config/loyaltyProgram'

import { getTranslatedText } from '@/tools/data'

import { validatePhoneNumber } from '@/tools/customValidations'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'
import customersActions from '@/store/customers/actions.types'

import setConfig from '@/components/LoyaltyViews/LoyaltyProgramView/EnrolledCustomersList/config'
import tools from '@/components/LoyaltyViews/LoyaltyProgramView/EnrolledCustomersList/enrolledCustomerList.tools'
import PaginatedTableSelection from '@/components/shared/PaginatedTableSelection'
import FormattedText from '@/components/shared/FormattedText'
import InfoCard from '@/components/shared/InfoCard'
import Button from '@/components/shared/CustomButton'
import LoyaltySettingsDialog from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltySettingsDialog'
import ConfirmDialog from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltySettingsDialog/ConfirmDialog'
import DeleteEnrolledCustomerDialog from '@/components/LoyaltyViews/LoyaltyProgramView/DeleteEnrolledCustomerDialog'
import AddEnrolledCustomersDialog from '@/components/LoyaltyViews/LoyaltyProgramView/AddEnrolledCustomersDialog'
import SendNotificationsDialog from '@/components/LoyaltyViews/LoyaltyProgramView/SendNotificationsDialog'
import InputPhone from '@/components/LoyaltyViews/InputPhone'

export default {
  name: 'EnrolledCustomersList',
  components: {
    InputPhone,
    PaginatedTableSelection,
    FormattedText,
    InfoCard,
    LoyaltySettingsDialog,
    ConfirmDialog,
    DeleteEnrolledCustomerDialog,
    AddEnrolledCustomersDialog,
    Button,
    SendNotificationsDialog,
  },
  data() {
    return {
      selectedCustomers: [],
      hasInternetConnection: navigator.onLine,
    }
  },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapState('loyaltyProgramView', [
      'settingsDialog',
      'confirmSettingDialog',
      'deleteEnrolledCustomerDialog',
      'addEnrolledCustomersDialog',
      'sendNotificationsDialog',
    ]),
    ...mapState('account', {
      account: state => state.data,
    }),
    ...mapState('loyaltyProgram', ['fetching']),
    ...mapGetters('loyaltyProgram', ['getFilteredData']),
    ...mapGetters('account', ['getCountry']),
    tableComponentConfig() {
      return setConfig(
        {
          items: this.getFilteredData,
          windowHeight: this.windowSize.y,
          fetching: this.fetching,
          selectedItems: this.selectedCustomers,
        },
        {
          context: this,
          getChipColor: this.getChipColor,
          getStatusText: this.getStatusText,
        }
      )
    },
    loyaltyInfo() {
      return tools.getLoyaltyInfo.call(this)
    },
    enableDeleteGroupBtn() {
      return !(this.selectedCustomers.length > 0)
    },
    enableResendInvitationsGroupBtn() {
      return (
        this.selectedCustomers.length > 0 &&
        this.selectedCustomers.every(customer =>
          this.canSendInvitation(customer)
        )
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus,
      loyaltyProgramViewActions.setSettingsDialogStatus,
      loyaltyProgramViewActions.setSendNotificationsDialogStatus,
    ]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.updateEnrolledCustomerByProperties,
    ]),
    ...mapActions('customers', [customersActions.editCustomerField]),
    updateSelectedCustomers(customers) {
      this.selectedCustomers = customers
    },
    deleteEnrolledCustomer(enrolledCustomer) {
      const index = this.selectedCustomers.findIndex(
        selectedCustomer =>
          selectedCustomer.customerId === enrolledCustomer.customerId
      )
      if (index !== -1) {
        this.selectedCustomers.splice(index, 1)
      }
      this[loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus]({
        isOpen: true,
        selectedEnrolledCustomer: [enrolledCustomer],
        inBulk: false,
      })
    },
    deleteEnrolledCustomersInBulk() {
      this[loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus]({
        isOpen: true,
        selectedEnrolledCustomer: this.selectedCustomers,
        inBulk: true,
      })
    },
    resendInvitations(enrolledCustomers) {
      if (!navigator.onLine) {
        notificationsService.showError(
          'notification.loyaltyProgram.networkError',
          this.$vuetify.lang,
          {
            timeout: 8000,
          }
        )
        return
      }
      rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
        event: ENROLLED_CUSTOMERS_DB_API_EVENTS.events.sendInvitations.name,
        data: {
          enrolledCustomers: tools.updateAmountForEachEnrolledCustomer(
            enrolledCustomers
          ),
          securityData: this.account.security,
          storeName: this.account.storeName,
          phoneCode: this.getCountry.phoneCode,
          pos: this.account.pos,
        },
      })
    },
    getChipColor(enrolledCustomer) {
      return tools.getStatusChipColor.call(this, enrolledCustomer)
    },
    getStatusText(enrolledCustomer) {
      return tools.getStatusChipText.call(this, enrolledCustomer)
    },
    isCorrectPhoneNumber(phone) {
      return validatePhoneNumber(phone)
    },
    canSendInvitation(enrolledCustomer) {
      return (
        [enrolStatus.PENDING, enrolStatus.INVITATION_NOT_SEND].includes(
          enrolledCustomer.status
        ) && this.isCorrectPhoneNumber(enrolledCustomer.customer.phone)
      )
    },
    openSettingsDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'EnrolledCustomerList',
        name: 'Open settings dialog',
      })
      this[loyaltyProgramViewActions.setSettingsDialogStatus](true)
    },
    openSendNotificationsDialog(type) {
      this[loyaltyProgramViewActions.setSendNotificationsDialogStatus]({
        isOpen: true,
        type,
      })
    },
    async enrolledCustomersListener(event, payload) {
      const events = ENROLLED_CUSTOMERS_DB_API_EVENTS.events
      const replies = {
        [events.deleteEnrolledCustomers.replies.success]: () => {
          if (payload.data.inBulk) this.selectedCustomers = []
        },
        [events.sendInvitations.replies.success]: () =>
          (this.selectedCustomers = []),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    customerWasEditedListener(event, payload) {
      const replies = {
        [CUSTOMERS_DB_API_EVENTS.events.updateById.replies.success]: () => {
          tools.createSynchronizationOperation(payload.data)
          tools.updateCustomerAndEnrolledCustomerStore.call(this, payload.data)
          tools.sendInvitationToCustomerWithPhoneEdited.call(this, payload.data)
        },
        [CUSTOMERS_DB_API_EVENTS.events.updateById.replies.error]: () => {
          notificationsService.showError(
            'loyaltyProgramConfig.stepper.step2.errorSavePhone',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    checkInternetConnection() {
      this.hasInternetConnection = navigator.onLine
    },
  },
  created() {
    window.addEventListener('online', this.checkInternetConnection)
    window.addEventListener('offline', this.checkInternetConnection)
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
    rendererEventsService.subscribe(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.customerWasEditedListener
    )
    this.$root.$on(
      'delete-enrolled-customer-cancel',
      () => (this.selectedCustomers = [])
    )
  },
  beforeDestroy() {
    window.removeEventListener('online', this.checkInternetConnection)
    window.removeEventListener('offline', this.checkInternetConnection)
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
    rendererEventsService.removeListener(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.customerWasEditedListener
    )
    this.$root.$off('delete-enrolled-customer-cancel')
  },
}
</script>

<style lang="scss" scoped>
.paginated-table__header {
  height: 90px;
}
.no-user-select {
  user-select: none;
}
.info-card {
  min-width: 276px;
}
</style>
