const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-cog',
    title: 'loyaltyProgramView.settingsDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    isAcceptButtonDisabled: state.isAcceptButtonDisabled,
    height: 380,
    maxWidth: 500,
    id: 'loyalty-settings-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'LoyaltySettingsDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.saveSettings(),
  },
})

export default setConfig
