<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapGetters } from 'vuex'

import helpCategories from '@/config/helpCategories'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'
import helpCenterViewActions from '@/store/helpCenterView/actions.types'

import config from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltyToolbar/Operations/config'

import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'LoyaltyOperations',
  components: {
    ToolBar,
  },
  computed: {
    ...mapGetters('helpCenter', ['getFilteredData']),
    componentConfig() {
      return config(
        {
          videos: this.getFilteredData,
        },
        {
          openLoyaltySettings: this.openLoyaltySettings,
        }
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setSettingsDialogStatus,
    ]),
    ...mapActions('helpCenterView', [helpCenterViewActions.setVideoTypeFilter]),
    openLoyaltySettings() {
      this[loyaltyProgramViewActions.setSettingsDialogStatus](true)
    },
  },
  mounted() {
    this[helpCenterViewActions.setVideoTypeFilter]([helpCategories.loyalty])
  },
  beforeDestroy() {
    this[helpCenterViewActions.setVideoTypeFilter]([])
  },
}
</script>
