<template>
  <div>
    <div v-for="(field, index) in placeholders" :key="index">
      <v-text-field
        :id="`field-${index}`"
        v-if="field.type === 'store'"
        type="text"
        v-model="formData[field.name]"
        :label="getLabel(field)"
        filled
        rounded
        dense
        required
        readonly
        v-show="false"
      />
      <v-text-field
        :id="`field-${index}`"
        v-if="field.type === 'string'"
        class="custom-text-field"
        type="text"
        maxlength="40"
        v-model="formData[field.name]"
        :label="getLabel(field)"
        filled
        rounded
        dense
        required
      />
      <v-text-field
        :id="`field-${index}`"
        v-if="field.type === 'number'"
        class="custom-text-field"
        type="number"
        v-model="formData[field.name]"
        :label="getLabel(field)"
        filled
        rounded
        dense
      />
      <v-text-field
        :id="`field-${index}`"
        v-if="field.type === 'time'"
        class="custom-text-field"
        type="time"
        v-model="formData[field.name]"
        :label="getLabel(field)"
        filled
        rounded
        dense
      />
      <DatePicker
        :id="`field-${index}`"
        v-if="field.type === 'date'"
        v-model="formData[field.name]"
        :label="getLabel(field)"
        :error-messages="errors[field.name]"
      />
      <ProductAutoComplete
        v-if="field.type === 'product'"
        v-model="formData[field.name]"
        :items="products"
        :customFilter="customFilter"
        itemValue="text"
        :label="getLabel(field)"
        :menu-props="{ 'max-width': '560px' }"
        className="custom-text-field"
        return-object
        clearable
      />
      <MoneyTextField
        v-if="field.type === 'price'"
        ref="price"
        v-model.number="formData[field.name]"
        :config="{
          fieldName: 'formData[field.name]',
          label: getLabel(field),
          color: 'primary',
          filled: true,
          rounded: true,
          class: 'custom-text-field-large',
          errorMessage: () => {},
        }"
        :options="moneyInputsConfig"
      />
      <MoneyTextField
        v-if="field.type === 'product-price'"
        ref="product-price"
        v-model.number="formData[field.name]"
        :config="{
          fieldName: 'formData[field.name]',
          label: getLabel(field),
          color: 'primary',
          filled: true,
          rounded: true,
          readonly: true,
          class: 'custom-text-field-large',
          errorMessage: () => {},
        }"
        :options="moneyInputsConfig"
      />
      <v-autocomplete
        v-if="field.type === 'more4less'"
        v-model.number="formData[field.name]"
        :items="promotionsFiltered"
        :label="getLabel(field)"
        class="custom-text-field"
        item-text="product.name"
        filled
        rounded
        return-object
      />
    </div>
  </div>
</template>

<script>
import { isNil } from 'ramda'
import { mapState, mapGetters } from 'vuex'

import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'
import {
  moneyTextFieldCountryConfig,
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
} from '@/tools/numbersFormat'
import { getDateWithFormat } from '@/tools/dates'

import ProductAutoComplete from '@/components/shared/ProductAutoComplete'
import MoneyTextField from '@/components/shared/MoneyTextField'
import DatePicker from '@/components/shared/DatePicker'

export default {
  name: 'DynamicForm',
  components: { ProductAutoComplete, MoneyTextField, DatePicker },
  props: {
    placeholders: {
      type: Array,
      required: true,
    },
  },
  data() {
    return {
      formData: {},
      menuStates: {},
      errors: {},
    }
  },
  computed: {
    ...mapState('products', ['data']),
    ...mapState('account', {
      storeName: state => state.data.storeName,
    }),
    ...mapGetters('customPromotions', [
      'getCustomPromotionsByProductAndTypeWithFilters',
    ]),
    isFormComplete() {
      this.validateDateRange()
      return this.placeholders.every(field => {
        const value =
          this.formData[field.name]?.trim?.() ?? this.formData[field.name]
        return value && !this.errors[field.name]
      })
    },
    promotionsFiltered() {
      const placeholderToPromotionMap = {
        more4less: promotions.SALE_ITEM_MORE_FOR_LESS,
        // TODO Add combo
      }
      const matchedTypes = this.placeholders.find(placeholder =>
        Object.keys(placeholderToPromotionMap).includes(placeholder.type)
      )
      return Object.values(
        this.getCustomPromotionsByProductAndTypeWithFilters(
          placeholderToPromotionMap[matchedTypes.type],
          { isActive: true }
        )
      )
    },
    products() {
      return this.getProductsFromInventory()
    },
    moneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
  },
  methods: {
    getTranslatedText,
    getDateWithFormat,
    validateDateRange() {
      const startDate = this.formData['fecha-inicio']
      const endDate = this.formData['fecha-fin']
      if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
        this.$set(
          this.errors,
          'fecha-fin',
          this.getTranslatedText(
            'loyaltyProgramView.sendNotificationsDialog.steps.step1.validation.dateError'
          )
        )
      } else {
        this.$set(this.errors, 'fecha-fin', null)
      }
    },
    customFilter(item, queryText) {
      return (
        item.name.toLowerCase().indexOf(queryText.toLowerCase()) > -1 ||
        item.upc.toLowerCase().indexOf(queryText.toLowerCase()) > -1
      )
    },
    getLabel(field) {
      const textWithSpace = field.name.replace('-', ' ')
      return textWithSpace.charAt(0).toUpperCase() + textWithSpace.slice(1)
    },
    getProductsFromInventory() {
      return this.data.products.reduce((list, product) => {
        if (this.isAvailableProduct(product) && product.id > 0) {
          list.push({ ...product, text: this.getCompletedName(product) })
        }
        return list
      }, [])
    },
    getCompletedName(product) {
      return `${product.name} ${product.alternativeName}`
    },
    isAvailableProduct(product) {
      return product.isGeneric === 0 && product.airTime === 0
    },
    initializeFormData() {
      this.formData = {}
      this.menuStates = {}
      this.placeholders.forEach(field => {
        const initialValue = this.getInitialValueForField(field)
        this.$set(this.formData, field.name, initialValue)
        if (field.type === 'date') {
          this.$set(this.menuStates, field.name, false)
        }
      })
    },
    getInitialValueForField(field) {
      switch (field.type) {
        case 'store':
          return this.storeName
        case 'price':
        case 'product-price':
        case 'more4less':
        case 'date':
          return null
        default:
          return ''
      }
    },
    getItemsRows(promotion) {
      const { promotions: promotionRows, product } = promotion
      const item = promotionRows[0]
      const sentence = this.getTranslatedText(
        'loyaltyProgramView.sendNotificationsDialog.steps.step1.more4less',
        [
          item.quantity,
          product.name,
          formatNumberFromDbToCurrency(item.promotionUnitPrice),
        ]
      )
      return sentence
    },
    updateFormData(newValue) {
      const updatedValue = { ...newValue }
      this.placeholders.forEach(field => {
        switch (field.type) {
          case 'date':
            this.handleDateField(updatedValue, field)
            break
          case 'more4less':
            this.handleMore4LessField(updatedValue, field)
            break
          case 'product':
            this.handleProductField(updatedValue, field)
            break
        }
      })
      return updatedValue
    },
    handleDateField(updatedValue, field) {
      const date = updatedValue[field.name]
      if (!isNil(date)) {
        updatedValue[field.name] = this.getDateWithFormat(date, 'DD-MM-YYYY')
      } else {
        this.$set(this.formData, field.name, null)
      }
    },
    handleMore4LessField(updatedValue, field) {
      const promotion = updatedValue[field.name]
      if (!isNil(promotion)) {
        const itemsRows = this.getItemsRows(promotion)
        updatedValue[field.name] = itemsRows
      } else {
        this.$set(this.formData, field.name, null)
      }
    },
    handleProductField(updatedValue, field) {
      const selectedProduct = updatedValue[field.name]
      const relatedPriceField = this.placeholders.find(
        f => f.type === 'product-price'
      )
      if (selectedProduct && relatedPriceField) {
        const formattedPrice = formatNumberFromDb(selectedProduct.price)
        updatedValue[field.name] = selectedProduct.name
        this.$set(this.formData, relatedPriceField.name, formattedPrice)
      } else if (relatedPriceField) {
        this.$set(this.formData, relatedPriceField.name, null)
      }
    },
  },
  watch: {
    formData: {
      handler(newValue) {
        const updatedData = this.updateFormData(newValue)
        this.$emit('form-updated', updatedData)
        this.$emit('form-valid', this.isFormComplete)
      },
      deep: true,
    },
    placeholders: {
      handler() {
        this.initializeFormData()
      },
      immediate: true,
    },
  },
  mounted() {
    this.initializeFormData()
  },
}
</script>
