<template>
  <PaginatedTableSelection
    class="py-2"
    :config="tableConfig"
    @updateSelectedItems="updateSelectedCustomers"
  >
    <template v-slot:top>
      <FormattedText
        intl
        value="loyaltyProgramView.sendNotificationsDialog.steps.step2.description"
        typeText="text-body-1"
      />
    </template>
  </PaginatedTableSelection>
</template>

<script>
import { mapGetters, mapState } from 'vuex'

import FormattedText from '@/components/shared/FormattedText'
import PaginatedTableSelection from '@/components/shared/PaginatedTableSelection'
import setTableConfig from '@/components/LoyaltyViews/LoyaltyProgramView/SendNotificationsDialog/NotificationSelectorStepper/steps/ChooseCustomers/tableConfig'

export default {
  name: 'ChooseCustomers',
  components: { FormattedText, PaginatedTableSelection },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapGetters('loyaltyProgram', ['approvedEnrolledCustomers']),
    tableConfig() {
      return setTableConfig(
        {
          items: this.approvedEnrolledCustomers,
          selectedItems: this.selectedCustomers,
          windowHeight: this.windowSize.y,
        },
        {
          context: this,
        }
      )
    },
  },
  methods: {
    updateSelectedCustomers(selectedItems) {
      this.$emit('selected-customers', selectedItems)
    },
  },
}
</script>
