<template>
  <v-stepper v-model="currentStep" class="stepper">
    <!-- Stepper header -->
    <v-stepper-header non-linear class="stepper__header">
      <!-- Dynamic steps -->
      <template v-for="step in steps">
        <v-stepper-step
          :key="step.id"
          :step="step.step"
          :editable="step.editable"
          :complete="step.complete"
        >
          <FormatedText intl :value="step.name" />
        </v-stepper-step>
      </template>
    </v-stepper-header>
    <v-stepper-items>
      <v-stepper-content v-for="step in steps" :key="step.id" :step="step.step">
        <component
          class="component-step"
          :is="step.component"
          @template-selected="handleTemplate"
          @form-updated="updateFormData"
          @form-valid="updateFormValidity"
          @selected-customers="updateSelectedCustomers"
          :data="{ templateSelected, formData, customersToNotify }"
        />
        <div class="pt-2">
          <div class="d-flex justify-space-between my-4">
            <div>
              <CustomButton
                className="mx-2"
                color="accent"
                text="shared.cancel"
                intl
                textType="text-button"
                @click="onClickCancel"
                v-track:click="{
                  category: 'LoyaltyProgram',
                  screen: 'NotificationSteps',
                  name: 'Cancel',
                }"
              />
            </div>
            <div class="d-flex justify-end ">
              <transition name="fade">
                <CustomButton
                  v-if="showPreviousButton"
                  className="mx-2"
                  color="accent"
                  text="shared.previous"
                  intl
                  textType="text-button"
                  @click="previousStep"
                  v-track:click="{
                    category: 'LoyaltyProgram',
                    screen: 'NotificationSteps',
                    name: 'Go to previous step',
                  }"
                />
              </transition>
              <ButtonCountdown
                v-if="currentStep === steps.length"
                :action="submitForm"
                :duration="10"
                :disabled="isSubmit"
                text="shared.send"
                intl
                textType="text-button"
              />
              <CustomButton
                v-else
                className="mx-2"
                text="shared.continue"
                intl
                textType="text-button"
                :disabled="isNextStepButtonDisabled"
                @click="nextStep"
                v-track:click="{
                  category: 'LoyaltyProgram',
                  screen: 'NotificationSteps',
                  name: 'Go to next step',
                }"
              />
            </div>
          </div>
        </div>
      </v-stepper-content>
    </v-stepper-items>
  </v-stepper>
</template>

<script>
import { isNil, isEmpty } from 'ramda'
import { mapActions, mapGetters, mapState } from 'vuex'

import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import steps from '@/components/LoyaltyViews/LoyaltyProgramView/SendNotificationsDialog/NotificationSelectorStepper/stepperConfig'
import FormatedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'
import ButtonCountdown from '@/components/shared/ButtonCountdown'

export default {
  name: 'NotificationSelectorStepper',
  components: { FormatedText, CustomButton, ButtonCountdown },
  data() {
    return {
      currentStep: 1,
      steps: steps,
      templateSelected: null,
      formData: {},
      isFormValid: false,
      customersToNotify: [],
      isSubmit: false,
    }
  },
  computed: {
    ...mapState('account', { accountData: state => state.data }),
    ...mapState('loyaltyProgramView', ['sendNotificationsDialog']),
    ...mapGetters('account', ['getCountry']),
    showPreviousButton() {
      return this.currentStep > 1
    },
    isNextStepButtonDisabled() {
      return (
        isNil(this.templateSelected) ||
        (this.currentStep === 1 && !this.isFormValid) ||
        (this.currentStep === 2 && isEmpty(this.customersToNotify))
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setSendNotificationsDialogStatus,
    ]),
    onClickCancel() {
      this[loyaltyProgramViewActions.setSendNotificationsDialogStatus]({
        isOpen: false,
      })
    },
    previousStep() {
      if (this.currentStep === 1) return
      this.currentStep -= 1
    },
    nextStep() {
      this.currentStep += 1
    },
    submitForm() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'NotificationSteps',
        name: 'Submit',
        extra_data: {
          label1: 'template',
          value1: this.templateSelected.templateId,
        },
      })
      this.isSubmit = true
      rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
        event:
          ENROLLED_CUSTOMERS_DB_API_EVENTS.events.sendAdvertisementNotification
            .name,
        data: {
          notification: {
            notificationType: this.sendNotificationsDialog.type,
          },
          templateSelected: this.templateSelected,
          formData: this.formData,
          enrolledCustomers: this.customersToNotify,
          securityData: this.accountData.security,
          phoneCode: this.getCountry.phoneCode,
        },
      })
    },
    handleTemplate(template) {
      this.templateSelected = template
    },
    updateFormValidity(isComplete) {
      this.isFormValid = isComplete
    },
    updateFormData(data) {
      this.formData = data
    },
    updateSelectedCustomers(customers) {
      this.customersToNotify = customers
    },
    async enrolledCustomersListener(event, payload) {
      const events = ENROLLED_CUSTOMERS_DB_API_EVENTS.events
      const replies = {
        [events.sendAdvertisementNotification.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'send_notification',
            category: 'LoyaltyProgram',
            screen: 'NotificationSteps',
            name: 'Close dialog',
          })
          this.isSubmit = false
        },
        [events.sendAdvertisementNotification.replies.error]: () => {
          this.isSubmit = false
          this.$track({
            type: 'system',
            action: 'error',
            category: 'LoyaltyProgram',
            screen: 'NotificationSteps',
            name: 'Error sending notification',
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
  },
}
</script>

<style lang="scss" scoped>
.stepper {
  box-shadow: none !important;
  .stepper__header {
    box-shadow: none !important;
  }
  .component-step {
    height: 32.5rem;
  }
}
.theme--dark.v-sheet {
  background-color: transparent;
}
</style>
