<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import USER_INFORMATION_DB_API_EVENTS from '@/config/events/databaseAPI/userInformationEvents'

import { formatNumberToDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import setConfig from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltySettingsDialog/ConfirmDialog/config'

import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'ConfirmDialog',
  components: { DialogCard },
  data() {
    return {
      isChangeSettings: false,
    }
  },
  computed: {
    ...mapState('loyaltyProgramView', ['confirmSettingDialog']),
    dialogConfig() {
      return setConfig(
        {
          opened: this.confirmSettingDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          saveSettings: this.saveSettings,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setConfirmSettingDialogStatus,
    ]),
    closeDialog() {
      this[loyaltyProgramViewActions.setConfirmSettingDialogStatus]({
        isOpen: false,
      })
    },
    saveSettings() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'ConfirmSettingsDialog',
        name: 'Confirm',
      })
      const {
        rewardAmount,
        prizeDescription,
      } = this.confirmSettingDialog.formPayload.inputs
      rendererEventsService.send(USER_INFORMATION_DB_API_EVENTS.channel, {
        event: USER_INFORMATION_DB_API_EVENTS.events.update.name,
        data: {
          userId: 1,
          values: {
            reward_amount: formatNumberToDb(rewardAmount),
            prize_description: prizeDescription,
          },
        },
      })
    },
  },
}
</script>
