const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'loyaltyProgramView.deleteEnrolledCustomer.title',
    messages: state.multiple
      ? ['loyaltyProgramView.deleteEnrolledCustomer.descriptionPlural']
      : ['loyaltyProgramView.deleteEnrolledCustomer.description'],
    titleColor: 'textPrimary',
    height: 225,
    maxWidth: 500,
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'DeleteEnrolledCustomerDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.removeEnrolledCustomer(),
  },
})

export default setConfig
