<template>
  <v-dialog
    v-model="sendNotificationsDialog.isOpen"
    max-width="1000"
    :overlay-opacity="0.15"
    @click:outside="onClickCancel"
  >
    <v-card flat color="cardBackgroundPrimary">
      <v-card-title>
        <v-icon left>
          mdi-message-reply-outline
        </v-icon>
        <FormattedText intl :value="dialogTitle" />
      </v-card-title>
      <v-row no-gutters>
        <v-col cols="12">
          <NotificationSelectorStepper />
        </v-col>
      </v-row>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { loyaltyNotificationType } from '@/config/loyaltyProgram'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import NotificationSelectorStepper from '@/components/LoyaltyViews/LoyaltyProgramView/SendNotificationsDialog/NotificationSelectorStepper'

export default {
  name: 'SendNotificationsDialog',
  components: { FormattedText, NotificationSelectorStepper },
  computed: {
    ...mapState('loyaltyProgramView', ['sendNotificationsDialog']),
    dialogTitle() {
      return `loyaltyProgramView.sendNotificationsDialog.${
        this.sendNotificationsDialog.type ===
        loyaltyNotificationType.NOTIFICATION
          ? 'titleNotification'
          : 'titlePromotion'
      }`
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setSendNotificationsDialogStatus,
    ]),
    onClickCancel() {
      this[loyaltyProgramViewActions.setSendNotificationsDialogStatus]({
        isOpen: false,
      })
    },
  },
}
</script>
