<template>
  <v-row no-gutters>
    <v-col cols="5" class="px-2 mr-10" align-self="center">
      <MobileMockup
        class="mobile"
        :message="processedText"
        :messageTitle="messageTitle"
        :messageFooter="
          getTranslatedText(
            'loyaltyProgramView.sendNotificationsDialog.steps.step1.messageFooter'
          )
        "
      />
    </v-col>
    <v-col class="template-selector pa-2">
      <FormattedText
        intl
        value="loyaltyProgramView.sendNotificationsDialog.steps.step1.description"
        typeText="text-body-1"
      />
      <div>
        <v-autocomplete
          id="template-autocomplete"
          v-model="selectedtemplate"
          :items="getTemplates"
          :label="
            getTranslatedText(
              'loyaltyProgramView.sendNotificationsDialog.steps.step1.templateLabel'
            )
          "
          item-text="name"
          item-value="id"
          class="custom-text-field"
          filled
          rounded
          return-object
          clearable
          ref="refsAutocomplete"
        />
      </div>
      <div class="fill-height" v-if="selectedtemplate">
        <DynamicForm
          :placeholders="placeholders"
          @form-updated="handleFormUpdate"
          @form-valid="handleFormValidity"
        />
      </div>
    </v-col>
  </v-row>
</template>

<script>
import { isNil } from 'ramda'
import { mapGetters, mapState } from 'vuex'

import { loyaltyNotificationType } from '@/config/loyaltyProgram'

import { getTranslatedText } from '@/tools/data'
import { formatNumberToCurrency } from '@/tools/numbersFormat'

import DynamicForm from '@/components/LoyaltyViews/LoyaltyProgramView/SendNotificationsDialog/NotificationSelectorStepper/DynamicForm'
import MobileMockup from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/MobileMockup'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ChooseTemplate',
  components: { MobileMockup, FormattedText, DynamicForm },
  data() {
    return {
      selectedtemplate: null,
      processedText: '',
      placeholders: [],
      formData: {},
    }
  },
  computed: {
    ...mapState('account', {
      storeName: state => state.data.storeName,
    }),
    ...mapState('loyaltyProgramView', ['sendNotificationsDialog']),
    ...mapGetters('whatsappTemplates', [
      'notificationTemplates',
      'promotionsTemplates',
    ]),
    messageTitle() {
      return isNil(this.selectedtemplate)
        ? ''
        : this.selectedtemplate.messageTitle
    },
    getTemplates() {
      return this.sendNotificationsDialog.type ===
        loyaltyNotificationType.NOTIFICATION
        ? this.notificationTemplates
        : this.promotionsTemplates
    },
  },
  methods: {
    getTranslatedText,
    parseTemplate(template) {
      const regex = /{([a-zA-Z0-9-_]+):(string|number|date|time|product|store|price|product-price|more4less)}/g
      let matches = []
      let match
      let processedMessage = template
      while ((match = regex.exec(template)) !== null) {
        matches.push({
          name: match[1],
          type: match[2],
        })
        processedMessage = processedMessage.replace(match[0], `{${match[1]}}`)
      }
      this.processedMessage = processedMessage
      return matches
    },
    replacePlaceholders() {
      let updatedText = this.selectedtemplate.message
      this.placeholders.forEach(placeholder => {
        const regex = new RegExp(
          `{${placeholder.name}:${placeholder.type}}`,
          'g'
        )
        let replacement = `<span style="color: var(--v-error-base); font-weight: bold;">{${placeholder.name}}</span>`
        if (placeholder.type === 'store') {
          replacement = this.storeName
        } else if (
          ['product-price', 'price'].includes(placeholder.type) &&
          this.formData[placeholder.name]
        ) {
          replacement =
            formatNumberToCurrency(this.formData[placeholder.name]) ||
            replacement
        } else if (this.formData[placeholder.name]) {
          replacement = this.formData[placeholder.name]
        }
        updatedText = updatedText.replace(regex, replacement)
      })
      this.processedText = updatedText
    },
    handleFormUpdate(formData) {
      this.formData = formData
      this.replacePlaceholders()
      this.$emit('form-updated', this.formData)
    },
    handleFormValidity(isComplete) {
      this.$emit('form-valid', isComplete)
    },
  },
  watch: {
    selectedtemplate() {
      this.$emit('template-selected', this.selectedtemplate)
      if (isNil(this.selectedtemplate)) {
        this.placeholders = []
        this.processedText = ''
        this.formData = {}
        this.$emit('form-updated', this.formData)
        this.$emit('form-valid', false)
        return
      }
      this.placeholders = this.parseTemplate(this.selectedtemplate.message)
      this.replacePlaceholders()
      this.$emit('form-valid', false)
    },
  },
}
</script>

<style lang="scss" scoped>
.mobile {
  mask-image: linear-gradient(to top, transparent 0%, black 15%);
}
.template-selector {
  font-size: 1rem;
  display: flex;
  flex-direction: column;
  row-gap: 1.1rem;
}
</style>
