<template>
  <v-container fluid class="loyalty-dashboard-view" id="loyalty-dashboard-view">
    <v-row no-gutters>
      <v-col
        class="loyalty-dashboard-view__filter-toolbar px-6 pt-6"
        id="loyalty-dashboard-view__filter-toolbar"
      >
        <LoyaltyToolbar />
      </v-col>
    </v-row>
    <v-row no-gutters>
      <v-col
        class="loyalty-dashboard-view__customers-list"
        id="loyalty-dashboard-view__customers-list"
        :style="{
          height: `calc(100vh - ${getCustomersListStyles}px)`,
        }"
      >
        <EnrolledCustomersList />
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { isEmpty, isNil } from 'ramda'

import USER_INFORMATION_DB_API_EVENTS from '@/config/events/databaseAPI/userInformationEvents'
import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'
import WHATSAPP_TEMPLATES_API_EVENTS from '@/config/events/serversAPI/whatsappTemplates'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'
import { getDiffBetweenDates, toDate } from '@/tools/dates'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'
import accountActions from '@/store/account/actions.types'
import appActions from '@/store/app/actions.types'
import whatsappTemplatesActions from '@/store/whatsappTemplates/actions.types'

import LoyaltyToolbar from '@/components/LoyaltyViews/LoyaltyProgramView/LoyaltyToolbar'
import EnrolledCustomersList from '@/components/LoyaltyViews/LoyaltyProgramView/EnrolledCustomersList'

export default {
  name: 'LoyaltyProgramView',
  components: { LoyaltyToolbar, EnrolledCustomersList },
  data() {
    return {
      layoutCommonElementsHeight: 0,
    }
  },
  computed: {
    ...mapState('app', ['pendingSyncOps']),
    ...mapState('loyaltyProgram', {
      enrolledCustomers: state => state.data.enrolledCustomers,
    }),
    ...mapState('account', {
      accountData: state => state.data,
    }),
    ...mapState('whatsappTemplates', {
      whatsappTemplates: state => state.templates,
      lastFetch: state => state.lastFetch,
    }),
    getCustomersListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setConfirmSettingDialogStatus,
      loyaltyProgramViewActions.setSettingsDialogStatus,
      loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus,
      loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus,
      loyaltyProgramViewActions.setSendNotificationsDialogStatus,
    ]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.deleteEnrolledCustomer,
      loyaltyProgramActions.deleteEnrolledCustomers,
      loyaltyProgramActions.setLoyaltyFetching,
      loyaltyProgramActions.setEnrolledCustomers,
      loyaltyProgramActions.updateEnrolledCustomer,
      loyaltyProgramActions.updateEnrolledCustomerByProperties,
    ]),
    ...mapActions('account', [accountActions.setLoyaltyData]),
    ...mapActions('app', [appActions.addPendingSyncOperation]),
    ...mapActions('whatsappTemplates', [
      whatsappTemplatesActions.setWhatsappTemplates,
    ]),
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'loyalty-dashboard-view'
      )
      const loyaltyToolbar = document.getElementById(
        'loyalty-dashboard-view__filter-toolbar'
      ).offsetHeight

      this.layoutCommonElementsHeight = layoutComponentsHeight + loyaltyToolbar
    },
    getWhatsappTemplates() {
      rendererEventsService.send(WHATSAPP_TEMPLATES_API_EVENTS.channel, {
        event: WHATSAPP_TEMPLATES_API_EVENTS.events.getWhatsappTemplates.name,
        data: {
          token: this.accountData.security.token,
        },
      })
    },
    getTemplatesIfTodayChanged() {
      if (getDiffBetweenDates(toDate(), this.lastFetch, 'day') === 0) {
        return
      }
      this.getWhatsappTemplates()
    },
    async userInformationListener(event, payload) {
      const events = USER_INFORMATION_DB_API_EVENTS.events
      const replies = {
        [events.update.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'save_settings',
            category: 'LoyaltyProgram',
            screen: 'LoyaltySettingsDialog',
            name: 'Close dialog',
          })
          const {
            reward_amount,
            prize_description,
            loyalty_program_actived,
          } = payload.data.data
          this[accountActions.setLoyaltyData]({
            loyaltyProgramActived: 1,
            rewardAmount: reward_amount,
            prizeDescription: prize_description,
          })
          rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
            event: SYNCHRONIZATION_EVENTS.events.createOperation.name,
            data: {
              entityData: {
                loyalty_program_actived: !!loyalty_program_actived,
                reward_amount,
                prize_description,
              },
              entityName: 'loyaltyprogram',
            },
          })
          this[appActions.addPendingSyncOperation]()
          this[loyaltyProgramViewActions.setConfirmSettingDialogStatus]({
            isOpen: false,
          })
          this[loyaltyProgramViewActions.setSettingsDialogStatus](false)
          notificationsService.showSuccess(
            'notification.loyaltyProgram.changeSettingsSuccess',
            this.$vuetify.lang
          )
        },
        [events.update.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'LoyaltyProgram',
            screen: 'LoyaltySettingsDialog',
            name: 'Error saving settings',
          })
          this[loyaltyProgramViewActions.setConfirmSettingDialogStatus]({
            isOpen: false,
          })
          this[loyaltyProgramViewActions.setSettingsDialogStatus](false)
          notificationsService.showError(
            'notification.loyaltyProgram.changeSettingsError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async enrolledCustomersListener(event, payload) {
      const events = ENROLLED_CUSTOMERS_DB_API_EVENTS.events
      const replies = {
        [events.add.replies.success]: () => {
          const { enrolledCustomers, customers, sales } = payload.data
          this[loyaltyProgramActions.setLoyaltyFetching](true)
          this[loyaltyProgramActions.setEnrolledCustomers]({
            enrolledCustomers,
            customers,
            sales,
          })
          this[appActions.addPendingSyncOperation]()
          this[loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus](
            false
          )
          this.$root.$emit('sendOpsToSync')
          notificationsService.showSuccess(
            'notification.loyaltyProgram.addEnrolledCustomerSuccess',
            this.$vuetify.lang
          )
        },
        [events.add.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'LoyaltyProgram',
            screen: 'AddEnrolledCustomersDialog',
            name: 'Error adding enrolled customers',
          })
          this[loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus](
            false
          )
          notificationsService.showError(
            'notification.loyaltyProgram.addEnrolledCustomerError',
            this.$vuetify.lang
          )
        },
        [events.deleteEnrolledCustomers.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_enrolled_customer',
            category: 'LoyaltyProgram',
            screen: 'DeleteEnrolledCustomerDialog',
            name: 'Close dialog',
          })
          this[loyaltyProgramActions.deleteEnrolledCustomers](
            payload.data.enrolledCustomers
          )
          this[
            loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus
          ]({ isOpen: false })
          this[appActions.addPendingSyncOperation]()
          this.$root.$emit('sendOpsToSync')
          notificationsService.showSuccess(
            'notification.loyaltyProgram.deleteEnrolledCustomerSuccess',
            this.$vuetify.lang
          )
        },
        [events.deleteEnrolledCustomers.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'LoyaltyProgram',
            screen: 'DeleteEnrolledCustomerDialog',
            name: 'Error deleting enrolled customer',
          })
          this[
            loyaltyProgramViewActions.setDeleteEnrolledCustomerDialogStatus
          ]({ isOpen: false })
          notificationsService.showError(
            'notification.loyaltyProgram.deleteEnrolledCustomerError',
            this.$vuetify.lang
          )
        },
        [events.checkInvitations.replies.success]: () => {
          const { enrolledCustomers } = payload.data
          enrolledCustomers.map(enrolledCustomer => {
            this[loyaltyProgramActions.updateEnrolledCustomer](enrolledCustomer)
          })
        },
        [events.checkInvitations.replies.error]: () =>
          notificationsService.showError(
            'notification.loyaltyProgram.checkInvitationsError',
            this.$vuetify.lang
          ),
        [events.sendInvitations.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'send_invitation',
            category: 'LoyaltyProgram',
            screen: 'EnrolledCustomerList',
            name: 'Update enrolled customers',
          })
          const { enrolledCustomersToUpdate } = payload.data
          enrolledCustomersToUpdate.forEach(enrolledCustomer => {
            this[loyaltyProgramActions.updateEnrolledCustomerByProperties]({
              ...enrolledCustomer,
            })
          })
          this[loyaltyProgramActions.setLoyaltyFetching](false)
          notificationsService.showSuccess(
            'notification.loyaltyProgram.sendInvitationsSuccess',
            this.$vuetify.lang
          )
        },
        [events.sendInvitations.replies.someError]: () => {
          this.$track({
            type: 'system',
            action: 'send_some_invitation',
            category: 'LoyaltyProgram',
            screen: 'EnrolledCustomerList',
            name: 'Update enrolled customers',
          })
          const { enrolledCustomersToUpdate } = payload.data
          enrolledCustomersToUpdate.forEach(enrolledCustomer => {
            this[loyaltyProgramActions.updateEnrolledCustomerByProperties]({
              ...enrolledCustomer,
            })
          })
          this[loyaltyProgramActions.setLoyaltyFetching](false)
          notificationsService.showWarning(
            'notification.loyaltyProgram.sendInvitationsSomeError',
            this.$vuetify.lang
          )
        },
        [events.sendInvitations.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'LoyaltyProgram',
            screen: 'EnrolledCustomerList',
            name: 'Error sending invitation',
          })
          this[loyaltyProgramActions.setLoyaltyFetching](false)
          notificationsService.showError(
            'notification.loyaltyProgram.sendInvitationsError',
            this.$vuetify.lang
          )
        },
        [events.sendAdvertisementNotification.replies.success]: () => {
          this[loyaltyProgramViewActions.setSendNotificationsDialogStatus]({
            isOpen: false,
          })
          notificationsService.showSuccess(
            'notification.loyaltyProgram.sendAdvertisementSuccess',
            this.$vuetify.lang
          )
        },
        [events.sendAdvertisementNotification.replies.error]: () => {
          this[loyaltyProgramViewActions.setSendNotificationsDialogStatus]({
            isOpen: false,
          })
          notificationsService.showError(
            'notification.loyaltyProgram.sendAdvertisementError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async whatsappTemplatesListener(event, payload) {
      const whatsappEvents = WHATSAPP_TEMPLATES_API_EVENTS.events
      const replies = {
        [whatsappEvents.getWhatsappTemplates.replies.success]: () => {
          this[whatsappTemplatesActions.setWhatsappTemplates](payload.data)
        },
        [whatsappEvents.getWhatsappTemplates.replies.error]: () => {
          this[whatsappTemplatesActions.setWhatsappTemplates]([])
          notificationsService.showError(
            'notification.loyaltyProgram.getWhatsappTemplatesError',
            this.$vuetify.lang,
            { timeout: 10000 }
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      USER_INFORMATION_DB_API_EVENTS.replyChannel,
      this.userInformationListener
    )
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
    rendererEventsService.subscribe(
      WHATSAPP_TEMPLATES_API_EVENTS.replyChannel,
      this.whatsappTemplatesListener
    )
    this.$root.$on('appComponentWasUpdated', this.getTemplatesIfTodayChanged)
  },
  mounted() {
    this.getLayoutHeight()
    if (navigator.onLine) {
      rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
        event: ENROLLED_CUSTOMERS_DB_API_EVENTS.events.checkInvitations.name,
        data: {
          enrolledCustomers: this.enrolledCustomers,
          securityData: this.accountData.security,
        },
      })
      if (isEmpty(this.whatsappTemplates) || isNil(this.whatsappTemplates)) {
        this.getWhatsappTemplates()
      }
    }
  },
  beforeDestroy() {
    this.$root.$off('appComponentWasUpdated', this.getTemplatesIfTodayChanged)
    rendererEventsService.removeListener(
      USER_INFORMATION_DB_API_EVENTS.replyChannel,
      this.userInformationListener
    )
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
    rendererEventsService.removeListener(
      WHATSAPP_TEMPLATES_API_EVENTS.replyChannel,
      this.whatsappTemplatesListener
    )
  },
}
</script>

<style lang="scss" scoped>
.loyalty-dashboard-view {
  height: 100%;
  .loyalty-dashboard-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .loyalty-dashboard-view__customers-list {
    width: 100%;
  }
}
</style>
