<template>
  <v-menu
    ref="menu"
    v-model="menu"
    :close-on-content-click="false"
    :return-value.sync="date"
    transition="scale-transition"
    offset-y
    top
    origin="bottom"
    min-width="auto"
  >
    <template v-slot:activator="{ on, attrs }">
      <v-text-field
        :value="dateText"
        :label="labelText"
        prepend-inner-icon="mdi-calendar"
        readonly
        filled
        rounded
        clearable
        :disabled="readonly"
        class="custom-text-field date-picker"
        v-bind="attrs"
        :hide-details="hideDetails"
        :error-messages="errorMessages"
        @keydown="on.keydown"
        @click:clear="resetValue"
        @click:prepend-inner="on.click"
      />
    </template>
    <v-date-picker
      v-model="date"
      no-title
      scrollable
      :locale="datePickerLocale"
      :min="minDate"
      :max="maxDate"
      :readonly="readonly"
      first-day-of-week="1"
      class="py-2"
    />
  </v-menu>
</template>

<script>
import { mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'
import { formatDate, getNow } from '@/tools/dates'

export default {
  name: 'DatePicker',
  props: {
    value: {
      type: String,
      default: '',
    },
    label: {
      type: String,
      default: 'datePicker.date',
    },
    intl: {
      type: Boolean,
      default: false,
    },
    minDate: {
      type: String,
      default: undefined,
    },
    maxDate: {
      type: String,
      default: undefined,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    hideDetails: {
      type: Boolean,
      default: false,
    },
    errorMessages: {
      type: [Array, String],
      default: () => [],
    },
  },
  data() {
    return {
      menu: false,
    }
  },
  computed: {
    ...mapState('account', ['data']),
    date: {
      get() {
        return this.value
      },
      set(value) {
        this.$emit('input', value)
        this.$refs.menu.save(value)
      },
    },
    labelText() {
      return this.intl ? this.getTranslatedText(this.label) : this.label
    },
    dateText() {
      return this.value ? formatDate(this.value) : ''
    },
    datePickerLocale() {
      return `${this.data.country.language}-${this.data.country.localeIsoCode}`
    },
  },
  methods: {
    getNow,
    formatDate,
    getTranslatedText,
    resetValue() {
      this.$emit('input', '')
    },
  },
  mounted() {
    const datePickerEl = this.$el.getElementsByClassName(`date-picker`)[0]
    const inputSlotEl = datePickerEl.getElementsByClassName('v-input__slot')[0]
    inputSlotEl.addEventListener('click', () => {
      if (!this.$refs.menu.isActive) {
        this.menu = true
      }
    })
  },
}
</script>
