const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-account-multiple-plus',
    title: 'loyaltyProgramView.addEnrolledCustomersDialog.title',
    titleColor: 'textPrimary',
    maxWidth: 500,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    isAcceptButtonDisabled: state.isAcceptButtonDisabled,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'AddEnrolledCustomersDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.openMessageInvitationDialog(),
  },
})

export default setConfig
