<template>
  <DialogCard :config="dialogConfig.dialogData">
    <div class="d-flex justify-space-between align-start">
      <v-autocomplete
        id="customer-autocomplete"
        v-model="selectedCustomers"
        :items="uninvitedCustomers"
        :label="
          getTranslatedText(
            'loyaltyProgramView.addEnrolledCustomersDialog.customers'
          )
        "
        item-text="name"
        item-value="id"
        class="custom-text-field"
        filled
        rounded
        chips
        multiple
        return-object
        ref="refsAutocomplete"
      >
        <!-- List item -->
        <template v-slot:item="data">
          <v-list-item-content>
            <v-list-item-title class="ellipsis">
              {{ data.item.name }}
            </v-list-item-title>
            <v-list-item-subtitle
              v-if="!!data.item.phone"
              :class="{ 'incorrect-phone': !hasValidPhone(data.item) }"
            >
              {{ data.item.phone }}
            </v-list-item-subtitle>
            <v-list-item-subtitle v-else>
              {{
                getTranslatedText(
                  'loyaltyProgramView.addEnrolledCustomersDialog.noPhone'
                )
              }}
            </v-list-item-subtitle>
          </v-list-item-content>
        </template>
        <template v-slot:append-item>
          <v-divider class="mt-2 mx-4" />
          <v-list class="pb-0">
            <v-list-item
              class="create-new-customer"
              @click="createNewCustomer"
              v-track:click="{
                category: 'LoyaltyProgram',
                screen: 'AddEnrolledCustomersDialog',
                name: 'Create customer',
              }"
            >
              <v-list-item-icon class="mr-2">
                <v-icon color="primary">mdi-plus</v-icon>
              </v-list-item-icon>
              <v-list-item-content>
                <v-list-item-title class="primary--text text-button">
                  {{
                    getTranslatedText(
                      'loyaltyProgramView.addEnrolledCustomersDialog.createCustomer'
                    )
                  }}
                </v-list-item-title>
              </v-list-item-content>
            </v-list-item>
          </v-list>
        </template>
        <!-- chip template for item selected -->
        <template v-slot:selection="data">
          <v-tooltip :disabled="hasValidPhone(data.item)" bottom>
            <template v-slot:activator="{ on }">
              <v-chip
                :input-value="data.selected"
                v-on="on"
                chip-ellipsis
                v-bind="data.attrs"
                :color="
                  hasValidPhone(data.item) ? 'chipPrimary' : 'chipSecondary'
                "
                close
                @click:close="removeItem(data.item)"
              >
                {{ getTruncatedText(data.item.name, 20) }}
              </v-chip>
            </template>
            <span>{{
              getTranslatedText(
                'loyaltyProgramView.addEnrolledCustomersDialog.invalidPhone'
              )
            }}</span>
          </v-tooltip>
        </template>
      </v-autocomplete>
      <v-tooltip bottom>
        <template v-slot:activator="{ on }">
          <v-icon
            v-on="on"
            class="ml-4 mt-6"
            color="salesPrimary"
            @click="createNewCustomer"
            v-track:click="{
              category: 'LoyaltyProgram',
              screen: 'AddEnrolledCustomersDialog',
              name: 'Create customer',
            }"
          >
            mdi-plus
          </v-icon>
        </template>
        <span>{{
          getTranslatedText('customersView.toolbar.buttons.addCustomer')
        }}</span>
      </v-tooltip>
    </div>
  </DialogCard>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'

import { getTruncatedText, getTranslatedText } from '@/tools/data'
import { validatePhoneNumber } from '@/tools/customValidations'
import { formatNumberFromDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'
import customersViewActions from '@/store/customersView/actions.types'

import setConfig from '@/components/LoyaltyViews/LoyaltyProgramView/AddEnrolledCustomersDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'AddEnrolledCustomersDialog',
  components: { DialogCard },
  data() {
    return {
      selectedCustomers: [],
      isAddingEnrolledCustomer: false,
    }
  },
  computed: {
    ...mapState('loyaltyProgramView', ['addEnrolledCustomersDialog']),
    ...mapState('customers', {
      customers: state => state.data.customers,
    }),
    ...mapState('loyaltyProgram', {
      enrolledCustomers: state => state.data.enrolledCustomers,
    }),
    ...mapState('account', {
      account: state => state.data,
    }),
    ...mapGetters('account', ['getCountry']),
    isAcceptButtonDisabled() {
      return this.selectedCustomers.length <= 0
    },
    dialogConfig() {
      return setConfig(
        {
          opened: this.addEnrolledCustomersDialog.isOpen,
          isAcceptButtonDisabled: this.isAcceptButtonDisabled,
        },
        {
          closeDialog: this.closeDialog,
          openMessageInvitationDialog: this.openMessageInvitationDialog,
          track: this.$track,
        }
      )
    },
    uninvitedCustomers() {
      return this.customers.filter(customer => {
        return !this.enrolledCustomers.some(
          enrolledCustomer => enrolledCustomer.customerId === customer.id
        )
      })
    },
  },
  methods: {
    getTruncatedText,
    getTranslatedText,
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus,
      loyaltyProgramViewActions.setMessageInformationDialogStatus,
    ]),
    ...mapActions('customersView', [
      customersViewActions.setAddCustomerDialogStatus,
    ]),
    closeDialog() {
      this[loyaltyProgramViewActions.setAddEnrolledCustomersDialogStatus](false)
    },
    removeItem(item) {
      this.selectedCustomers = this.selectedCustomers.filter(
        customer => customer.id !== item.id
      )
    },
    hasValidPhone(customer) {
      return validatePhoneNumber(customer.phone)
    },
    createNewCustomer() {
      this.$refs.refsAutocomplete.blur()
      this[customersViewActions.setAddCustomerDialogStatus](true)
    },
    addNewCustomerToEnroll(customerId) {
      const customerFound = this.customers.find(
        customer => customer.id === customerId
      )
      if (!customerFound) return
      this.selectedCustomers.push(customerFound)
    },
    onAcceptMessageInvitacion() {
      if (!navigator.onLine) {
        notificationsService.showError(
          'notification.loyaltyProgram.networkError',
          this.$vuetify.lang,
          {
            timeout: 8000,
          }
        )
        return
      }
      if (this.isAddingEnrolledCustomer) return
      this.$track({
        type: 'system',
        action: 'confirm_invitation',
        category: 'LoyaltyProgram',
        screen: 'AddEnrolledCustomersDialog',
        name: 'Close dialog',
      })
      this.isAddingEnrolledCustomer = true
      rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
        event: ENROLLED_CUSTOMERS_DB_API_EVENTS.events.add.name,
        data: {
          customers: this.selectedCustomers,
          loyaltyProgramConfig: this.account.loyaltyProgram,
          rewardAmountFormatted: formatNumberFromDb(
            this.account.loyaltyProgram.rewardAmount
          ),
          phoneCode: this.getCountry.phoneCode,
          storeName: this.account.storeName,
          securityData: this.account.security,
          pos: this.account.pos,
        },
      })
      this.closeDialog()
    },
    openMessageInvitationDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'AddEnrolledCustomersDialog',
        name: 'Show whatsapp message',
      })
      this[loyaltyProgramViewActions.setMessageInformationDialogStatus]({
        isOpen: true,
        data: {
          loyaltyFormInputs: {
            rewardAmount: this.account.loyaltyProgram.rewardAmount,
            storeName: this.account.storeName,
          },
          customersAdded: this.selectedCustomers,
        },
      })
    },
    async enrolledCustomerListener(event, payload) {
      const addEnrolledCustomerReplies =
        ENROLLED_CUSTOMERS_DB_API_EVENTS.events.add.replies
      const replies = {
        [addEnrolledCustomerReplies.success]: () => {
          this.isAddingEnrolledCustomer = false
        },
        [addEnrolledCustomerReplies.error]: () => {
          this.isAddingEnrolledCustomer = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomerListener
    )
    this.$root.$on('loyalty-accept-message-invitation', () => {
      this.onAcceptMessageInvitacion()
    })
  },
  beforeMount() {
    this.$root.$on('customerAdded', this.addNewCustomerToEnroll)
  },
  beforeDestroy() {
    this.$root.$off('customerAdded', this.addNewCustomerToEnroll)
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomerListener
    )
    this.$root.$off('loyalty-accept-message-invitation')
  },
}
</script>

<style lang="scss" scoped>
.ellipsis {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 300px;
}
.chip-ellipsis {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 30px;
}
.incorrect-phone {
  text-decoration: var(--v-error-base) wavy underline;
}
.create-new-customer {
  &:before {
    background: var(--v-primary-base);
  }
}
</style>
