const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'loyaltyProgramView.confirmDialog.title',
    messages: ['loyaltyProgramView.confirmDialog.description'],
    titleColor: 'textPrimary',
    height: 250,
    maxWidth: 500,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgram',
        screen: 'ConfirmSettingsDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.saveSettings(),
  },
})

export default setConfig
